def balanced_split(nums):
    total = sum(nums)
    n = len(nums)
    target = total // 2
    dp = [False] * (target+1)
    dp[0] = True
    for num in nums:
        for s in range(target, num-1, -1):
            if dp[s-num]:
                dp[s] = True
    best = total
    for s in range(1, target+1):
        if dp[s] and s != total:
            diff = abs(total - 2*s)
            if diff < best:
                best = diff
    return best

def kth_char(S, k):
    n = len(S)
    if k <= n:
        return S[k-1]
    length = n
    while length < k:
        length *= 2
    def solve(length_now, k_pos):
        if k_pos <= n:
            return S[k_pos-1]
        half = length_now // 2
        if k_pos <= half:
            return solve(half, k_pos)
        mirrored = k_pos - half
        res = solve(half, half - mirrored + 1)
        return '1' if res == '0' else '0'
    return solve(length, k)

def min_swaps_to_equal(s1, s2):
    if len(s1) != len(s2):
        return -1
    xy = 0
    yx = 0
    for a,b in zip(s1, s2):
        if a == 'x' and b == 'y':
            xy += 1
        elif a == 'y' and b == 'x':
            yx += 1
    if (xy + yx) % 2 == 1:
        return -1
    return xy//2 + yx//2 + 2*(xy%2)

def longest_ap(arr):
    n = len(arr)
    if n <= 2:
        return n
    dp = [dict() for _ in range(n)]
    best = 2
    for i in range(n):
        for j in range(i):
            diff = arr[i] - arr[j]
            dp[i][diff] = dp[j].get(diff, 1) + 1
            if dp[i][diff] > best:
                best = dp[i][diff]
    return best

def count_arrays(n, k):
    if k < 0:
        return 0
    dp = [[0] * (k+1) for _ in range(n+1)]
    dp[0][0] = 1
    for i in range(1, n+1):
        for j in range(k+1):
            total = 0
            for x in range(min(j, i-1)+1):
                total += dp[i-1][j-x]
            dp[i][j] = total
    return dp[n][k]

def min_path_cost(cost, teleport):
    import heapq
    n = len(cost) + 1
    adj = [[] for _ in range(n)]
    for i in range(n-1):
        adj[i].append((i+1, cost[i]))
    for i, t in enumerate(teleport):
        if t is not None and 0 <= t < n:
            adj[i].append((t, 0))
    INF = 10**18
    dist = [INF] * n
    dist[0] = 0
    pq = [(0, 0)]
    while pq:
        d,u = heapq.heappop(pq)
        if d > dist[u]:
            continue
        for v,w in adj[u]:
            nd = d + w
            if nd < dist[v]:
                dist[v] = nd
                heapq.heappush(pq, (nd, v))
    return dist[n-1]
